from pathlib import Path
import pandas as pd
r=Path(__file__).resolve().parents[1];out=r/"phase24";mechanism=pd.read_csv(out/"mechanism_summary.csv");loso=pd.read_csv(out/"loso_summary.csv");people=pd.read_csv(out/"loso_people.csv");selected=loso[loso.policy.isin(["KEEP","WRITE","RESET","future20","future35","future435","current435","future_hgb35","future_confidence4","future435_write_only","current435_write_only","future20_write_only","future35_write_only","future_hgb35_write_only"])];per=people[people.policy.isin(["future435_write_only","current435_write_only"])]
html="<!doctype html><html lang=zh><meta charset=utf-8><title>完整训练模型的写入与回退可观察性</title><style>body{max-width:1200px;margin:40px auto;font:16px/1.7 system-ui}td,th{padding:6px;border-bottom:1px solid #ddd}.note{background:#fff2df;padding:18px}</style><h1>完整训练模型：写入与回退可观察性</h1><p class=note>这里不是目标人群测试成绩，也不是策略实际连续运行的成绩。4位预留控制器人员、2种来源模型、连续更新/每64窗口重置两种轨迹，共2168个反事实脉冲。每20窗口比较KEEP/RESET/COMMIT，未来4窗口中暂停更新，以平均任务CE衡量干预价值。单位为nats，正值有益。</p><p>理想选择的主要收益来自回退；单次新写入的理想收益约0.0005–0.0006nats。三动作收益预测器在留一人验证中均未获得正均值。限制为KEEP/COMMIT后，年轻来源的435维未来预测器有微弱正均值（4人中3人正），但同容量当前收益预测器均值更高；混合来源仍为负。不能据此认定未来收益学习的优势成立。</p><h2>反事实上限与实际单次写入</h2>"+mechanism.to_html(index=False,float_format=lambda x:f"{x:.6f}",border=0)+"<h2>跨人可观察性：每次只用另外3人的监督拟合</h2>"+selected.to_html(index=False,float_format=lambda x:f"{x:.6f}",border=0)+"<h2>微弱正均值的逐人检查</h2>"+per.to_html(index=False,float_format=lambda x:f"{x:.8f}",border=0)+"<p>基础20维、加入方向与因果历史的35维、加入当前源模型嵌入的435维分别比较；Ridge固定alpha100，另有35维浅树对照。置信度组同样使用未来收益监督，属于特征消融。当前收益组使用当前标签构造收益，作为预测目标消融。</p><p>反事实探测后精确恢复实际轨迹；源参数状态下RESET等于KEEP。所有未来标签、真实阶段、当前是否正确仅用于离线评分与分层，均不在特征白名单中。24个源控制器样本的当前嵌入在改变未来样本后完全不变，历史特征与仅使用前缀的计算完全一致。实际轨迹F1已独立复算。</p><p>接续phase25仅进行源验证集上的真实策略运行，与当前收益、固定更新间隔以及使用同一批未来标签的静态监督校准比较。尚无新目标评估结论。</p><p><a href=protocol.json>协议与特征白名单</a> · <a href=loso_people.csv>所有逐人值</a> · <a href=diagnostic_audit.json>诊断审计</a> · <a href=feature_causality_audit.json>特征因果性检查</a> · <a href=../phase23/report.html>连续更新的目标结果</a></p></html>"
(out/"report.html").write_text(html)
